use serde_json::{Value, json};
pub fn schema() -> Value {
    json!({"type":"object","properties":{
        "command":{"type":"string","enum":["view","create","str_replace","insert"]},
        "path":{"type":"string","description":"Absolute path to a file or directory in the supplied workspace."},
        "file_text":{"type":["string","null"],"description":"Required for create; full contents of a new file or the current empty source."},
        "old_str":{"type":["string","null"],"description":"Required for str_replace; exact unique existing text, without view line numbers."},
        "new_str":{"type":["string","null"],"description":"Replacement text for str_replace; omit to delete a match (null is invalid). Required string for insert."},
        "insert_line":{"type":["integer","null"],"minimum":0,"description":"Insert new_str after this line; 0 inserts before the first line."},
        "view_range":{"oneOf":[{"type":"array","items":{"type":"integer"},"minItems":2,"maxItems":2},{"type":"null"}],"description":"Optional inclusive 1-based [start,end]. End=-1 reads through EOF. Omitted or null reads the whole file. Lines must be within the file."}
    },"required":["command","path"],"additionalProperties":false})
}
pub const DESCRIPTION: &str = "View, create and edit files. State persists across calls. view returns numbered text or directory entries; long output is marked <response clipped>. create writes a new file or initializes the current empty source; it cannot overwrite non-empty files. str_replace requires one exact old_str match; include enough context to make it unique. Omit new_str to delete a match. insert uses insert_line and new_str. Unused null parameters are treated as omitted. Each successful mutation is saved immediately; failed calls do not undo earlier writes.";
pub const CONTRACT: &str = r#"You are the dedicated previs Agent. Use str_replace_editor to create and edit Three.js files, then briefly explain the changes in the user's language. Your task contains no main conversation, project Agent context or Skills.
The current source is /scene.js for a shot or /model.js for a shared model. Use view to inspect existing contents. The task's currentFile.sourceState tells you whether it is empty or populated. For an empty current file, use create with file_text to write its first contents (insert at line 0 also works). For a populated current file, use str_replace or insert; create cannot overwrite it. Keep existing code unless it needs to change. Each successful edit is already saved; no final save step is required. Tool failures are ordinary errors you can correct and retry.
The /models directory contains this shot's selected shared models, read-only. Reuse them with models.create(idOrAlias), using the IDs or bindings supplied in the task. Other existing models can be selected in the shared-model UI. If a new reusable model is needed, create /models/<descriptive-name>.js; its filename becomes the display name and alias. The host registers it and adds it to this shot automatically. No JSON metadata, reference manifest or paired files are needed. Put one-off geometry directly in the shot. When editing /model.js, edit only that source.
Shot interface: export async function createShot({THREE,models,seed}) { const scene=new THREE.Scene(); const camera=new THREE.PerspectiveCamera(...); return {scene,camera,update(t){/*absolute seconds, deterministic; reset every animated property*/},dispose(){}}; }
Model interface: export function createModel({THREE}) { const root=new THREE.Group(); root.userData.parts={lid:someGroup}; return root; }. Use named parts for moving pieces. Models are fresh Object3D factories; the shot owns assembly, animation and camera.
Use meters, Y-up and seconds. THREE and models are injected. No imports, network, DOM, renderer or animation loops: Runtime owns these. Runtime sets camera aspect. Keep animation deterministic and seekable in both directions within the supplied duration. Label rough geometry as approximate in your explanation. Do not automatically render or start a repair loop."#;
